WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, MAX(session_start_flag) FILTER (WHERE merchant = 'Grab') AS grab_max_session_start_flag, COUNT_IF(merchant = 'Grab') AS grab_events FROM sessions_transactions GROUP BY quarter_start HAVING COUNT_IF(merchant = 'Grab') >= 1 ORDER BY quarter_start DESC
